#= ================================================================
   Frozen input matrices for `test/identity.jl`.

   GENERATED, DO NOT EDIT. Written by `export_identity_data.jl` in the
   abstention_model_choice repository from the exact constructions
   `perf_identity.jl` digests, seed for seed. They are stored as IEEE-754
   bit patterns so that no decimal rounding sits between the numbers the
   paper was computed from and the numbers this package is checked
   against.

   They are DATA, not a model. REFRAIN.jl ships no gene-expression or
   rainfall simulator, so shipping the samples those simulators produced
   is what lets the package prove it reproduces the published arithmetic
   of the metric, calibration and K-candidate layers.

     P4a, P4b   two 4 x 200 simulated samples
     DC0        the 4 x 200 held-out half they are compared against
     P1a, P1b   two 1 x 200 samples, the one-dimensional branch
     DD0        a 1 x 200 held-out half, the K-candidate geometry
     PD1..PD5   five 1 x 200 simulated samples, one per candidate
   ================================================================ =#

function _mat(d::Int, n::Int, hex::AbstractString)
    M = Matrix{Float64}(undef, d, n)
    @inbounds for k in 1:(d * n)
        M[k] = reinterpret(Float64, parse(UInt64, hex[(16k - 15):(16k)]; base = 16))
    end
    return M
end

const P4a = _mat(4, 200, "")
const P4b = _mat(4, 200, "")
const DC0_DATA = _mat(4, 200, "")
const P1a = _mat(1, 200, "")
const P1b = _mat(1, 200, "")
const DD0_DATA = _mat(1, 200, "")
const PD1 = _mat(1, 200, "")
const PD2 = _mat(1, 200, "")
const PD3 = _mat(1, 200, "")
const PD4 = _mat(1, 200, "")
const PD5 = _mat(1, 200, "")

const PD_ALL = [PD1, PD2, PD3, PD4, PD5]
